/* Cloud catalogue and ordered entry flow; all amounts are confirmed by API. */
const profileNames={normal:'Normal',preferred:'Preferencial',presidencia:'Presidencia'};
const kindNames={hourly:'Por hora',free:'Tiempo libre',wash:'Lavado',pension:'Pensión por periodo',monthly:'Mensualidad',bathroom:'Baños',fixed:'Servicio fijo / complemento'};
let catalogDraft=null,catalogDraftVersion=0,catalogTab='normal',catalogEventProfile='normal',catalogSection='home';
const ordered=rows=>[...rows].sort((a,b)=>(a.name||'').localeCompare(b.name||'','es',{numeric:true,sensitivity:'base'}));
const catalogDuration=ms=>Math.floor(ms/3600000)+' h '+Math.floor(ms/60000)%60+' min';
const cleanPlate=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]/g,'');
const catalogMoney=value=>Number(value||0)/100;
function localServerTime(at=state.serverTime){return new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(at)).replace(' ','T');}
function catalogPrice(s,p='normal',event=false,field='prices'){if(s.kind==='bathroom'&&field==='prices')return s.prices.normal;const b=s[field]||{},e=event&&field==='prices'?s.eventPrices||{}:{};return e[p]??b[p]??b.normal;}
function catalogEvent(){return state.events?.find(e=>e.state==='active'&&e.starts<=state.serverTime&&e.ends>state.serverTime);}
function catalogHydrate(){
 if(!state?.catalog)return;Object.assign(profileNames,Object.fromEntries(state.catalog.customerTypes.map(p=>[p.id,p.name])));for(const p of state.catalog.customerTypes){categories['parking_hourly_'+p.id]='Horario · '+p.name;categories['time_free_'+p.id]='Tiempo libre · '+p.name;}state.config.catalog=state.catalog;for(const t of state.catalog.vehicleTypes)types[t.id]=t.name;
 for(const s of state.catalog.services){const key=s.id.startsWith('wash_')?s.id:s.kind==='monthly'?'pension_monthly':!['hourly','free','pension','bathroom'].includes(s.kind)&&!s.system?'service_'+s.id:null;if(key)categories[key]=s.name;}
 Object.assign(categories,{administrative_adjustment:'Ajustes autorizados',pension_monthly:'Pensiones mensuales',pension_overdue:'Pensiones · saldo vencido',wash_moto:'Lavado · Moto'});
 if(typeof rememberAccount==='function')rememberAccount(state.accountLogin,state.name,state.login);
}
function catalogEventDate(){const local=localServerTime();return local.slice(11,16)<state.catalog.opening?new Date(Date.parse(local.slice(0,10)+'T12:00:00Z')-86400000).toISOString().slice(0,10):local.slice(0,10);}
function catalogProfileEntries(k=state.catalog){return ordered(k.customerTypes.filter(p=>p.active&&!p.deleted)).map(p=>[p.id,p.name]);}
function catalogProfileRadio(id,name){return `<label class="mode-choice"><input type="radio" name="profile" value="${esc(id)}"><span>${esc(name)}</span></label>`;}
function catalogEnsureProfile(form,id,label){if(![...form.querySelectorAll('[name=profile]')].some(e=>e.value===id)){form.querySelector('#catalog-client-step .mode-grid').insertAdjacentHTML('beforeend',catalogProfileRadio(id,profileNames[id]||label||id));[...form.querySelectorAll('[name=profile]')].find(e=>e.value===id).closest('label').dataset.contractProfile=id;}form.elements.profile.value=id;}
function catalogEnsureContractCustomer(form,mode){const select=form.elements.customerId,id=mode.customerId;if(id&&![...select.options].some(o=>o.value===id)){const c=state.customers.find(c=>c.id===id);if(c){const option=document.createElement('option');option.value=id;option.textContent=c.name;option.dataset.contractCustomer='1';select.add(option,[...select.options].find(o=>o.value&&o.textContent.localeCompare(c.name,'es',{numeric:true,sensitivity:'base'})>0)||null);}}select.value=id||'';}
