 const modules=[['ajustes','settings','Tarifas'],['clientes','shield','Clientes y saldos'],...(state.catalog.services.some(s=>s.active&&s.kind==='fixed'&&s.parking==='none'&&!s.system)?[['servicios','check','Servicios']]:[]),['reportes','report','Reportes'],['tarjetas','cards','Tarjetas QR'],['equipo','shield','Equipo']];
 $('#main').innerHTML=heading('RESUMEN','El Oeste','Cobros confirmados y operación actual.',catalogEvent()?`<div class="summary-event"><span class="pill">Modo evento activo · Cierre ${clock(catalogEvent().ends)}</span><button class="secondary" data-catalog="event-end" data-id="${catalogEvent().id}">Finalizar modo evento</button></div>`:'<button class="primary" data-catalog="event-start">Activar modo evento</button>')+`<section class="business-ledger catalog-ledger"><div class="ledger-income"><span class="hero-label">Ingresos de hoy</span><strong>${money(r.total)}</strong><p>${r.payments.length} pagos recibidos</p></div><div class="ledger-occupancy"><span class="hero-label">Ocupación</span><strong>${state.stays.length}<small> / ${state.capacity}</small></strong><p>${state.capacity-state.stays.length} disponibles</p></div><div class="ledger-debt"><span class="hero-label">Pendiente de Presidencia</span><strong class="catalog-balance">${money(totalDebt)}</strong></div></section><div class="admin-grid gap-top">${modules.map(([id,i,n])=>`<button class="admin-link" data-tab="${id}">${icon(i)}<span>${n}</span></button>`).join('')}</div>${notices.length?`<section class="panel gap-top"><h2>Pensiones por atender</h2>${notices.map(n=>`<p class="gap-top">${esc(n)}</p>`).join('')}</section>`:''}<details class="panel gap-top"><summary>Aplicación y equipos</summary><div class="compact-actions gap-top">${[['perifericos','Periféricos'],['respaldos','Respaldos'],['actualizaciones','Aplicación']].map(([id,n])=>`<button class="secondary" data-tab="${id}">${n}</button>`).join('')}</div></details>`;
