 const f=$('#entry-form');if(context.card)f.elements.card.value=context.card;
 if(context.contractId){const m=state.monthly.find(m=>m.id===context.contractId);if(m){f.elements.plate.value=JSON.parse(m.vehicle).plate;f.dataset.monthly=context.contractId;f.dataset.matched=cleanPlate(f.elements.plate.value);const mode=JSON.parse(m.mode);catalogEnsureProfile(f,mode.profile||'normal',mode.profileName);catalogEnsureContractCustomer(f,mode);}}
