 e.serviceId.innerHTML='<option value="">'+(vehicleType?'Selecciona el servicio':'Selecciona primero el vehículo')+'</option>'+contracts.map(m=>`<option value="m:${m.id}">Pensión vigente · ${esc(JSON.parse(m.mode).name||JSON.parse(m.mode).serviceLabel)}</option>`).join('')+ordered(services).map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${money(catalogPrice(s,profile,!!catalogEvent()))}${s.kind==='hourly'?'/h':''}</option>`).join('');
 if(old&&[...e.serviceId.options].some(o=>o.value===old))e.serviceId.value=old;else if(contracts.length===1)e.serviceId.value='m:'+contracts[0].id;
