 $('#catalog-parking').hidden=!s||s.parking!=='addon';$('#catalog-parking-copy').textContent='Estacionamiento · '+money(s?catalogPrice(s,profile,false,'addonPrices'):0);if(!s||s.parking!=='addon')e.parkingSelected.checked=false;
