 openModal('Salida · '+esc(v.plate||cardNumber(stay.card_id)),`<form id="catalog-checkout-form" data-id="${id}" class="management-form"><p>${esc(s.serviceLabel)} · ${profileNames[s.profile]}</p><div class="catalog-breakdown">${q.lines.map(l=>`<div class="summary-line"><span>${esc(l.label)}</span><b>${money(l.cents)}</b></div>`).join('')}</div>${q.overdueMs?`<p class="note gap-top">${s.kind==='monthly'&&q.coverageEnd<s.contractEnd?'Tiempo de visita excedido':'Pensión vencida'} · ${catalogDuration(q.overdueMs)} transcurridos desde ${dateTime(q.coverageEnd)}.</p>`:''}<div class="summary-total"><span>Total a cobrar</span><strong id="catalog-total">${money(q.total)}</strong></div>${s.profile==='presidencia'?`<label class="gap-top">Registrar como<select name="collection"><option value="paid">Pago recibido</option><option value="account">A cuenta de ${esc(state.customers.find(c=>c.id===s.customerId)?.name||'Presidencia')}</option></select></label>`:''}<details class="gap-top catalog-adjustment" id="catalog-adjustment"><summary>${state.role==='admin'?'Ajustar importe':'Autorizar ajuste'}</summary><input name="resolve" type="checkbox" hidden><p class="fine gap-top">Calculado: ${money(q.total)}. El importe acordado se aplica al confirmar el cobro.</p><label class="gap-top">Importe acordado · MXN<input name="resolvedTotal" type="number" min="0" step="0.01" value="${(q.total/100).toFixed(2)}"></label><label class="gap-top">Motivo del ajuste<input name="reason" minlength="4" maxlength="500" autocomplete="off"></label>${state.role==='admin'?'':`<label class="gap-top">Usuario administrador<input name="adminName" autocomplete="off"></label><label class="gap-top">PIN administrador<input name="adminPin" type="password" inputmode="numeric" autocomplete="off"></label>`}<button type="button" class="ghost gap-top" data-discard-adjustment>Descartar ajuste</button></details>${managementActions('Confirmar pago y salida',false)}<div class="compact-actions gap-top"><button type="button" class="ghost" data-cancel-entry="${id}">Cancelar entrada</button>${s.kind==='wash'?`<button type="button" class="ghost" data-catalog="cancel-wash" data-id="${id}">Cancelar lavado</button>`:''}${!s.lostCard?`<button type="button" class="ghost" data-catalog="lost" data-id="${id}">Tarjeta extraviada</button>`:stay.card_state==='lost'&&state.role==='admin'?`<button type="button" class="ghost" data-replace-card="${id}">Asignar otra tarjeta</button>`:''}</div></form>`);
