 const adjustmentForm=$('#catalog-checkout-form'),adjustment=$('#catalog-adjustment');const syncAdjustment=()=>{const e=adjustmentForm.elements,on=adjustment.open;e.resolve.checked=on;for(const key of ['resolvedTotal','reason','adminName','adminPin'])if(e[key])e[key].required=on;if(!on&&e.adminPin)e.adminPin.value='';let total=q.total;if(on&&e.resolvedTotal.value!==''&&e.resolvedTotal.validity.valid){try{total=cents(e.resolvedTotal.value);}catch{}}$('#catalog-total').textContent=money(total);};adjustment.addEventListener('toggle',syncAdjustment);adjustment.addEventListener('input',syncAdjustment);adjustmentForm.querySelector('[data-discard-adjustment]').addEventListener('click',()=>{adjustment.open=false;adjustmentForm.elements.resolvedTotal.value=(q.total/100).toFixed(2);adjustmentForm.elements.reason.value='';syncAdjustment();});syncAdjustment();
 managementForm('catalog-checkout-form',async f=>{const e=f.elements,b={id,expectedTotal:q.total,vehicleConfirmed:true,onAccount:e.collection?.value==='account',paymentConfirmed:e.collection?.value!=='account'};if(adjustment.open)Object.assign(b,{resolvedTotal:cents(e.resolvedTotal.value),reason:e.reason.value,adminName:e.adminName?.value,adminPin:e.adminPin?.value});let result;try{result=await request('catalog-checkout',b);}catch(error){if(error.code==='CREDENTIALS'&&e.adminPin)e.adminPin.value='';if(!document.documentElement.classList.contains('cloud-offline')&&['TOTAL_CHANGED','CONFLICT'].includes(error.code)){await refresh(false);if(state?.stays.some(s=>s.id===id)){catalogCheckoutView(id);$('#catalog-checkout-form [role=alert]').textContent=error.message;}else{closeModal();toast(error.message);}return;}throw error;}closeModal();await refresh();toast(result.onAccount?'Salida registrada a cuenta.':'Pago y salida registrados.');});
