function catalogReadTypes(config,form){for(const t of config.catalog.vehicleTypes){const name=form.elements['type_'+t.id],active=form.elements['active_'+t.id];if(name&&name.value.trim())t.name=name.value.trim();if(active)t.active=active.checked;}}
function catalogDeletePlan(config,kind,id){
 if(!['type','service','profile'].includes(kind))throw Error('Opción desconocida.');const next=structuredClone(config),k=next.catalog,items=kind==='type'?k.vehicleTypes:kind==='profile'?k.customerTypes:k.services,item=items.find(v=>v.id===id&&!v.deleted);if(!item)throw Error('La opción ya no está disponible.');const affected=[];
 if(kind==='type'){
  if(!k.vehicleTypes.some(t=>t.id!==id&&t.active&&!t.deleted))throw Error('Conserva al menos un tipo de vehículo activo.');
  item.active=false;item.deleted=true;
  for(const service of k.services)if(service.active&&service.vehicleTypes.includes(id)&&!service.vehicleTypes.some(type=>k.vehicleTypes.some(t=>t.id===type&&t.active&&!t.deleted))){service.active=false;service.typeSelectionRequired=true;affected.push(service.name);}
 }else if(kind==='profile'){if(id==='normal')throw Error('Normal es el precio base y debe permanecer activo.');item.active=false;item.deleted=true;
 }else{
  const rules=[['nightRateId','pensión nocturna'],['overdueShortId','periodo vencido corto'],['overdueLongId','periodo vencido largo']].filter(([key])=>k[key]===id).map(([,name])=>name);
  if(rules.length)throw Error('Primero selecciona otra opción para '+rules.join(', ')+' en Horarios y reglas de pensiones.');
  if(item.kind==='hourly'&&!k.services.some(s=>s.id!==id&&s.kind==='hourly'&&s.active&&!s.deleted))throw Error('Conserva un servicio por hora activo para el cobro al reabrir.');
  item.active=false;item.deleted=true;
 }
 if(!k.services.some(s=>s.active&&!s.deleted&&s.kind==='hourly'))throw Error('Conserva un servicio por hora activo.');for(const key of ['nightRateId','overdueShortId','overdueLongId'])if(!k.services.some(s=>s.id===k[key]&&s.active&&!s.deleted))throw Error('Este tipo se usa en una pensión de cierre o vencimiento. Reasigna sus vehículos antes de eliminarlo.');
 return {config:next,name:item.name,affected};
}
